/**
 * Returns the level descriptor for an id.
 * @param id level index 0..LEVEL_COUNT-1 (clamped)
 * @return pointer to const level info; never NULL
 */
const LevelInfo* level_get(uint8_t id) {
    return &levels[id < LEVEL_COUNT ? id : 0];
}
